    /// <summary>
    /// Checks if the base enum value exist in the table.
    /// </summary>
    /// <param name = "enumName">The enum AOT name</param>
    /// <param name = "enumValue">The enum integer value</param>
    /// <param name = "enumText">The enum text</param>
    /// <returns>true, if the value exist, otherwise false</returns>
    public static boolean doesEnumValueExist(String255 enumName, int enumValue, Str60 enumText)
    {
        boolean ret = false;
        METMultiSelectBaseEnumTable metMultiSelectBaseEnumTable;

        select firstonly RecId from metMultiSelectBaseEnumTable
            where metMultiSelectBaseEnumTable.EnumName == enumName
            && metMultiSelectBaseEnumTable.EnumValue == enumValue
            && metMultiSelectBaseEnumTable.EnumText == enumText;

        if (metMultiSelectBaseEnumTable.RecId)
        {
            ret = true;
        }   

        return ret;
    }

    /// <summary>
    /// Finds record using EnumName and EnumText fields.
    /// </summary>
    /// <param name = "_enumName">The name of the base enum.</param>
    /// <param name = "_enumText">The text value of the enum element.</param>
    /// <param name = "_forUpdate">To update or not.</param>
    /// <param name = "_concurrencyModel">The concurrency model</param>
    /// <returns>The METMultiSelectBaseEnumTable buffer.</returns>
    public static METMultiSelectBaseEnumTable findByEnumValue(
        METEnumName _enumName,
        METEnumText _enumText,
        boolean _forUpdate = false,
        ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METMultiSelectBaseEnumTable metMultiSelectBaseEnumTable;
        
        metMultiSelectBaseEnumTable.selectForUpdate(_forUpdate);
        if (_forUpdate  && _concurrencyModel != ConcurrencyModel::Auto)
        {
            metMultiSelectBaseEnumTable.concurrencyModel(_concurrencyModel);
        }

        select firstonly metMultiSelectBaseEnumTable
            where metMultiSelectBaseEnumTable.EnumName == _enumName
            && metMultiSelectBaseEnumTable.EnumText == _enumText;

        return metMultiSelectBaseEnumTable;
    }
